// Extract job and candidates from webhook body
const body = $input.first().json.body || $input.first().json;

const job = body.job;
const candidates = body.candidates || [];

if (!job || !candidates.length) {
  return [{ json: { error: 'Missing job or candidates data', rankings: [] } }];
}

// === JOB SUMMARY (clean, structured) ===
const job_summary = {
  id: job.id,
  title: job.title,
  description: (job.description || '').replace(/<[^>]*>/g, '').slice(0, 800),
  skills_required: (job.skills_required || []),
  job_type: job.job_type || 'N/A',
  location: job.location || 'N/A',
  country: job.country || 'N/A',
  salary_range: job.salary_range || 'N/A',
};

// === CANDIDATES LIST (each with clean data) ===
const candidates_list = candidates.map((c, i) => ({
  index: i + 1,
  id: c.id,
  name: c.name || 'Unknown',
  headline: c.headline || '',
  skills: (c.skills || []),
  skills_text: (c.skills || []).join(', '),
  years_experience: c.years_experience || 0,
  location: c.location || '',
  nationality: c.nationality || '',
  education: (c.education || []),
  education_text: (c.education || []).join(' | '),
  summary: (c.summary || '').slice(0, 300),
  cv_url: c.cv_url || null,
}));

// === FULL PROMPT for AI ===
const jobText = `الوظيفة: ${job.title}
الوصف: ${job_summary.description}
المهارات المطلوبة: ${job_summary.skills_required.join(', ') || 'غير محدد'}
النوع: ${job_summary.job_type}
الموقع: ${job_summary.location}
الراتب: ${job_summary.salary_range}`;

const candidatesText = candidates_list.map(c => 
  `[مرشح ${c.index}] الاسم: ${c.name} | المهارات: ${c.skills_text} | الخبرة: ${c.years_experience} سنة | التعليم: ${c.education_text} | الملخص: ${c.summary}`
).join('\n');

const prompt = `أنت خبير توظيف ذكي في سوق العمل الإماراتي والعربي.

حلّل الوظيفة التالية وقيّم المرشحين حسب مناسبتهم.

قواعد مهمة:
1. قيّم التطابق الدلالي للمهارات (مثلاً React تتعلق بـ Frontend)
2. اعتبر المهارات القابلة للنقل والخبرة في المجال
3. طابق مستوى التعليم مع متطلبات الوظيفة
4. أعطِ وزناً أعلى للتطابق الدقيق في المهارات
5. أجب بـ JSON فقط بدون markdown

=== الوظيفة ===
${jobText}

=== المرشحون ===
${candidatesText}

=== التنسيق المطلوب ===
أرجع JSON بهذا الشكل بالضبط:
{
  "rankings": [
    {
      "candidate_id": "uuid",
      "name": "الاسم",
      "score": 0-100,
      "reasoning": "شرح بالعربي لماذا هذا المرشح مناسب أو غير مناسب (2-3 جمل)",
      "strengths": ["مهارة1", "مهارة2"],
      "gaps": ["مهارة_ناقصة1"],
      "recommendation": "مناسب جداً" | "مناسب" | "مناسب جزئياً" | "غير مناسب"
    }
  ]
}

رتّب من الأعلى للأقل. كن عادلاً وتحليلياً.`;

// === OUTPUT: Everything separated for easy wiring ===
return [{ json: {
  prompt,
  job_summary,
  candidates_list,
  candidates_text: candidatesText,
  job_text: jobText,
  metadata: {
    job_id: job.id,
    employer_id: body.employer_id,
    candidate_count: candidates.length,
    timestamp: new Date().toISOString(),
  }
} }];

// Parse Gemini response and clean it up
const rawText = $input.first().json.text || $input.first().json.response || '';

let result;
try {
  // Remove markdown code fences if present
  let cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  // Try to find JSON in the text
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      result = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      result = {
        rankings: [],
        error: 'Failed to parse AI response',
        raw: rawText.slice(0, 500)
      };
    }
  } else {
    result = {
      rankings: [],
      error: 'No JSON found in AI response',
      raw: rawText.slice(0, 500)
    };
  }
}

// Ensure rankings exist and are sorted
if (result.rankings && Array.isArray(result.rankings)) {
  result.rankings.sort((a, b) => (b.score || 0) - (a.score || 0));
}

return [{ json: result }];
